SELECT o.status, CASE WHEN o.status IN ('COMPLETED', 'RETURNED') THEN 'core' ELSE 'other' END AS status_group, ROUND(AVG(p.amount), 2) AS avg_amount, SORT_ARRAY(COLLECT_SET(p.status)) AS status_list FROM payments p JOIN orders o ON o.id = p.order_id JOIN customers c ON o.customer_id = c.id GROUP BY o.status, CASE WHEN o.status IN ('COMPLETED', 'RETURNED') THEN 'core' ELSE 'other' END ORDER BY status_group DESC, avg_amount DESC
